INSERT INTO DimAccount (SK_AccountID, AccountID, SK_BrokerID, SK_CustomerID, Status, AccountDesc, TaxStatus, IsCurrent, BatchID, EffectiveDate, EndDate) WITH AccountEvents AS (SELECT CAST(Acc.CA_ID AS INT) AS AccountID, C.C_ID AS CustomerID, Act.ActionType, TRY_CAST(Act.ActionTS AS TIMESTAMP) AS ActionTS, TRY_CAST(Act.Action_Id AS BIGINT) AS ActionSeq, TRY_CAST(Acc.CA_B_ID AS BIGINT) AS BrokerID, Acc.CA_NAME AS AccountDesc, TRY_CAST(Acc.CA_TAX_ST AS INT) AS TaxStatus FROM Source.CustomerXML AS C INNER JOIN Source.ActionXML AS Act ON C.Action_Id = Act.Action_Id INNER JOIN Source.AccountXML AS Acc ON C.Customer_Id = Acc.Customer_Id WHERE Act.ActionType IN ('NEW', 'ADDACCT', 'UPDACCT', 'CLOSEACCT')), AccountFirst AS (SELECT AccountID, MIN(CustomerID) AS CustomerID, CAST(MIN(ActionTS) AS DATE) AS FirstDay FROM AccountEvents GROUP BY AccountID), AccountTimeline AS (SELECT AccountID, CustomerID, ActionTS, ActionSeq, ActionType, BrokerID, AccountDesc, TaxStatus FROM AccountEvents UNION ALL SELECT F.AccountID, F.CustomerID, CAST(CV.EffectiveDate AS TIMESTAMP) + INTERVAL '23 hours 59 minutes 59 seconds' AS ActionTS, 999999999999 AS ActionSeq, 'CUSTCHANGE' AS ActionType, NULL AS BrokerID, NULL AS AccountDesc, NULL AS TaxStatus FROM AccountFirst AS F INNER JOIN DimCustomer AS CV ON CV.CustomerID = F.CustomerID AND CV.EffectiveDate > F.FirstDay), AccountFilled AS (SELECT AccountID, CustomerID, ActionTS, ActionSeq, LAST_VALUE(BrokerID IGNORE NULLS) OVER w AS BrokerID, AccountDesc AS AccountDesc, COALESCE(AccountTimeline.TaxStatus, 0) AS TaxStatus, MAX(CASE WHEN ActionType = 'CLOSEACCT' THEN 1 ELSE 0 END) OVER w AS WasClosed FROM AccountTimeline WINDOW w AS (PARTITION BY AccountID ORDER BY ActionTS, ActionSeq ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), AccountDaily AS (SELECT * FROM AccountFilled QUALIFY ROW_NUMBER() OVER (PARTITION BY AccountID, CAST(ActionTS AS DATE) ORDER BY ActionTS DESC, ActionSeq DESC) = 1), AccountVersions AS (SELECT D.AccountID, D.AccountDesc, D.TaxStatus, D.WasClosed, CAST(D.ActionTS AS DATE) AS EffectiveDate, COALESCE(LEAD(CAST(D.ActionTS AS DATE)) OVER (PARTITION BY D.AccountID ORDER BY D.ActionTS, D.ActionSeq), CAST('9999-12-31' AS DATE)) AS EndDate, Br.SK_BrokerID AS SK_BrokerID, Cu.SK_CustomerID AS SK_CustomerID, Cu.Status AS CustomerStatus FROM AccountDaily AS D LEFT JOIN DimBroker AS Br ON D.BrokerID = Br.BrokerID LEFT JOIN DimCustomer AS Cu ON Cu.CustomerID = D.CustomerID AND Cu.EffectiveDate <= CAST(D.ActionTS AS DATE) AND CAST(D.ActionTS AS DATE) < Cu.EndDate) SELECT CAST(ROW_NUMBER() OVER (ORDER BY AccountID, EffectiveDate) AS INT) AS SK_AccountID, CAST(AccountID AS INT) AS AccountID, CAST(SK_BrokerID AS INT) AS SK_BrokerID, CAST(SK_CustomerID AS INT) AS SK_CustomerID, CAST(CASE WHEN WasClosed = 1 THEN 'Closed' ELSE CustomerStatus END AS TEXT) AS Status, CAST(AccountDesc AS TEXT) AS AccountDesc, CAST(TaxStatus AS INT) AS TaxStatus, CAST(EndDate = CAST('9999-12-31' AS DATE) AS BOOLEAN) AS IsCurrent, CAST(1 AS INT) AS BatchID, CAST(EffectiveDate AS DATE) AS EffectiveDate, CAST(EndDate AS DATE) AS EndDate FROM AccountVersions ORDER BY AccountID, EffectiveDate ASC;
